import numpy as np
P=Path(__file__).resolve().parent;META=P.parent/'cold_full_envelope_data_2026_10_25/fit_002/result.json'
def calculate(n):
 meta=json.loads(META.read_text());r=np.geomspace(1e-7,1e8,n);G=.00430091;a0=9.3603e-11*3.085677581491367e10;rows=[]
 for row in meta['rows']:
  name=row['name'];d=meta['datasets'][name];target=row['fixed_supply_envelopes'][1];M=target['cold_mass_Msun'];R=np.sqrt(G*M/(.1*a0));V=np.sqrt(G*M/R);eta=1500/(R*V);vin=10/V;q=d['stellar_mass_Msun']/M;aa=np.array(d['tracer_scales_pc'])/R;b=target['scale_pc']/R;pb=sum(-q/len(aa)/np.sqrt(r*r+a*a) for a in aa);gn=sum(q/len(aa)*r/(r*r+a*a)**1.5 for a in aa);mg=4/np.sqrt(np.pi)*r*r*np.exp(-r*r);coefficient=.5*np.trapz(mg*r*r/(r*r+.05**2),r);E0=.75*eta*eta+coefficient*vin*vin-1/np.sqrt(2*np.pi)+np.trapz(mg*pb,r);dm=3*r*r*b*b/(r*r+b*b)**2.5;W=-3*np.pi/(32*b);Wn=.5*np.trapz(dm*(-1/np.sqrt(r*r+b*b)),r);Ub=np.trapz(dm*pb,r);Wb=-np.trapz(dm*r*gn,r);Kvir=-.5*(W+Wb);Evir=.5*W+Ub-.5*Wb;Kamp=.5*eta*eta*np.trapz(dm*(2.5*r/(r*r+b*b))**2,r);needed=Evir-(.75*eta*eta-1/np.sqrt(2*np.pi)+np.trapz(mg*pb,r));lam=np.sqrt(max(0,needed/coefficient));rows.append(dict(galaxy=name,beta=row['beta'],footing=row['footing'],M_Msun=M,R_pc=R,V_kms=V,b_over_R=b,E_initial=E0,E_virial_target=float(Evir),energy_gap=float(Evir-E0),needs_energy_input_if_no_hidden_binding=bool(Evir>E0),W_analytic=float(W),W_quadrature=float(Wn),W_relative_error=float(abs(Wn/W-1)),mass_quadrature=float(np.trapz(dm,r)),K_virial=float(Kvir),K_amplitude=float(Kamp),amplitude_support_fraction=float(Kamp/Kvir),minimal_vin_over_V_for_target_energy=float(lam),minimal_vin_kms=float(lam*V)))
 return rows
