 ap=argparse.ArgumentParser();ap.add_argument('--out',required=True);a=ap.parse_args();out=Path(a.out);out.mkdir(parents=True,exist_ok=True);assert not(out/'result.json').exists();start=time.time();coarse=calculate(65536);fine=calculate(131072);ref=max(abs(a['E_virial_target']-b['E_virial_target']) for a,b in zip(coarse,fine));err=max(r['W_relative_error'] for r in fine);assert err<1e-6 and ref<1e-6;d=dict(scope='conditional isolated stationary complete candidate energy screen; not a formation solution, not all data-allowed halos',rows=fine,quadrature_W_max_relative_error=err,quadrature_refinement_max_energy_difference=ref,source_sha256=hashlib.sha256(META.read_bytes()).hexdigest(),seconds=time.time()-start,peak_RSS_bytes=resource.getrusage(resource.RUSAGE_SELF).ru_maxrss);(out/'result.json').write_text(json.dumps(d,indent=2));print(json.dumps(dict(rows=len(fine),W_error=err,refinement=ref)))
